const auth = ($input.first().json.authorization || '').toString();
if (!auth.startsWith('Bearer ')) {
  return [{ json: { valid: false, code: 'AUTH_MISSING_TOKEN', status: 401 } }];
}
const token = auth.slice(7);
if (!token || token.split('.').length !== 3) {
  return [{ json: { valid: false, code: 'AUTH_INVALID_TOKEN', status: 401 } }];
}
// Decode payload sin verificar firma - solo para early reject de expirados
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (payload.exp && Date.now()/1000 > payload.exp) {
    return [{ json: { valid: false, code: 'AUTH_EXPIRED', status: 401 } }];
  }
  return [{ json: { token, payload_preview: { sub: payload.sub, exp: payload.exp } } }];
} catch (e) {
  return [{ json: { valid: false, code: 'AUTH_INVALID_TOKEN', status: 401, _details: e.message } }];
}

const resp = $input.first().json;
const pre  = $('Pre-decode JWT').first().json;

// neverError:true = revisar status manualmente
if (resp.statusCode && resp.statusCode >= 400) {
  return [{ json: {
    valid:  false,
    code:   'AUTH_INVALID_TOKEN',
    status: 401,
    _details: resp.message || 'Supabase rechazo el JWT'
  }}];
}

const user = resp.body || resp;
if (!user || !user.id) {
  return [{ json: { valid: false, code: 'AUTH_INVALID_TOKEN', status: 401 } }];
}

// Las custom claims viven en el JWT decoded, no en /auth/v1/user, asi que las leemos del token original
let tenantId = null;
let role     = 'architect';
let fullName = user.user_metadata?.full_name || null;
try {
  const payload = JSON.parse(Buffer.from(pre.token.split('.')[1], 'base64url').toString('utf8'));
  tenantId = payload.tenant_id || null;
  role     = payload.role      || role;
  fullName = payload.full_name || fullName;
} catch(e) {}

if (!tenantId) {
  return [{ json: {
    valid:  false,
    code:   'AUTH_NO_TENANT',
    status: 403,
    _details: 'JWT valido pero sin tenant_id custom claim. Auth Hook no configurado o user sin perfil activo.',
    user_id: user.id,
    email:   user.email
  }}];
}

return [{ json: {
  valid:     true,
  user_id:   user.id,
  email:     user.email,
  tenant_id: tenantId,
  role,
  full_name: fullName
}}];
